import pymupdf
def scan(path, pages=None):
    doc = pymupdf.open(path)
    print("=====", path, "pages:", doc.page_count)
    for pno in (pages or range(doc.page_count)):
        page = doc[pno]
        annots = list(page.annots() or [])
        if annots:
            for a in annots:
                print(f"  p{pno+1} ANNOT type={a.type} rect={a.rect} info={a.info}")
        d = page.get_text("dict")
        for b in d["blocks"]:
            for l in b.get("lines", []):
                for s in l["spans"]:
                    col = s["color"]
                    if col != 0 and s["text"].strip():
                        print(f"  p{pno+1} color={col:06x} size={s['size']:.1f} font={s['font']} text={s['text'][:150]!r}")
        # drawings (filled rects) that may cover text
        draws = page.get_drawings()
        whites = [dr for dr in draws if dr.get("fill") and all(c>0.95 for c in dr["fill"]) and dr["rect"].width>50 and dr["rect"].height>5]
        for w in whites[:20]:
            r = w["rect"]
            covered = page.get_textbox(r).strip()
            if covered:
                print(f"  p{pno+1} WHITE RECT {r} covers: {covered[:300]!r}")
scan("06_Construction/RFIs/RFI-041_Rock_Bent2.pdf")
scan("06_Construction/Field/Dailies_2026-03.pdf", pages=range(20,24))
EOF

