import pymupdf
def words_in(path, pno, rect):
    doc = pymupdf.open(path); page = doc[pno]
    r = pymupdf.Rect(rect)
    ws = [w for w in page.get_text("words") if pymupdf.Rect(w[:4]).intersects(r)]
    return " ".join(w[4] for w in ws)
