import pymupdf, glob
for path in sorted(glob.glob("**/*.pdf", recursive=True)):
    doc = pymupdf.open(path)
    found = []
    for pno in range(doc.page_count):
        page = doc[pno]
        for dr in page.get_drawings():
            f = dr.get("fill")
            r = dr["rect"]
            if f and all(c > 0.97 for c in f) and r.height < 20 and 25 < r.width < 450:
                # check if text spans fall inside the rect (true redaction-cover) or gap
                inside = [w[4] for w in page.get_text("words") if pymupdf.Rect(w[:4]).intersects(r) and pymupdf.Rect(w[:4]).get_area() and (pymupdf.Rect(w[:4]) & r).get_area() > 0.6*pymupdf.Rect(w[:4]).get_area()]
                found.append((pno+1, round(r.x0), round(r.y0), round(r.width), inside[:12]))
    if found:
        print("==", path)
        for f in found[:12]: print("   ", f)
